'use strict';
/* Xưởng Nội Dung v0.5.0 — adapter for reusable XUONG_TRUYEN standards. No separate app/server. */
const storyKinds={volume:'Tập',arc:'Tuyến truyện',chapter:'Kế hoạch chương',scene:'Cảnh',note:'Ghi chú chung'};
const storyThreadStates={open:'Đã gợi mở',developing:'Đang phát triển',resolved:'Đã giải quyết',dropped:'Đã bỏ'};
function storyData(s){s.story??={characters:[],plans:[],memories:[],translationConfig:{sourceLang:'vi',targetLang:'en',styles:{},terms:[]},importKeys:[]};for(const k of ['characters','plans','memories','importKeys'])if(!Array.isArray(s.story[k]))s.story[k]=[];return s.story}
function storyChapters(s){return db.content.filter(c=>c.seriesId===s.id&&c.productionTask!=='outline').sort((a,b)=>Number(a.chapterNumber||0)-Number(b.chapterNumber||0))}
function storyPlanPath(s,p){const plans=storyData(s).plans,out=[];let x=p,guard=0;while(x&&guard++<20){out.unshift(x.title);x=plans.find(q=>q.id===x.parentId)}return out.join(' › ')}
function storySelectedPlans(s,n){const plans=storyData(s).plans,chosen=new Set(plans.filter(p=>!p.kind||p.kind==='note').map(p=>p.id));for(const p of plans)if(p.kind&&p.kind!=='note'&&Number(p.startChapter)<=n&&Number(p.endChapter)>=n){chosen.add(p.id);let q=p;while(q?.parentId){chosen.add(q.parentId);q=plans.find(x=>x.id===q.parentId)}}return plans.filter(p=>chosen.has(p.id))}
function storyThreadAlerts(s,n){return storyData(s).memories.filter(m=>m.type==='Nút thắt'&&m.confirmed&&Number(m.chapter)<n&&!['resolved','dropped'].includes(m.threadStatus||'open')&&Number(m.dueChapter)>0&&Number(m.dueChapter)<=n)}
function storyContext(s,n){const sd=storyData(s),previous=storyChapters(s).filter(c=>Number(c.chapterNumber)<n&&['approved','live'].includes(c.status)).slice(-3),plans=storySelectedPlans(s,n),alerts=storyThreadAlerts(s,n);return ['Bạn là biên tập viên và tác giả truyện dài kỳ. Đây là bản nháp để con người duyệt.',`TRUYỆN: ${s.title}\nTHỂ LOẠI: ${s.genre||''}\nTIỀN ĐỀ: ${s.synopsis||''}\nTHẾ GIỚI: ${s.world||''}\nNHÂN VẬT:\n${sd.characters.map(x=>x.title+': '+x.body).join('\n')}`,`DÀN Ý LIÊN QUAN:\n${plans.map(p=>(storyKinds[p.kind]||'Ghi chú')+' / '+p.title+': '+p.body).join('\n')}`,`TRÍ NHỚ ĐÃ XÁC NHẬN:\n${sd.memories.filter(m=>m.confirmed&&Number(m.chapter)<n).map(m=>m.type+' / '+m.title+': '+m.body).join('\n')}`,`NÚT THẮT ĐẾN MỐC CẦN XEM XÉT:\n${alerts.map(m=>m.title+' — chương '+m.dueChapter).join('\n')}`,`CÁC CHƯƠNG TRƯỚC ĐÃ DUYỆT:\n${previous.map(c=>'Chương '+c.chapterNumber+': '+(c.summary||c.body)).join('\n\n')}`,'Giữ nhất quán nguyên nhân–kết quả, nhân vật, thời gian và địa điểm. Không tự đổi sự kiện đã xác nhận. Nút thắt đến mốc chỉ là cảnh báo, không tự kết luận đã giải quyết. Không tự đăng.'].join('\n\n')}
function storyCreateDraft(s){const n=Math.max(0,...storyChapters(s).map(c=>Number(c.chapterNumber)||0))+1;openEditor('content','',{title:'Chapter '+n+' — '+s.title,channelId:s.channelId,seriesId:s.id,status:'draft',kind:'Chương truyện',chapterNumber:n,productionTask:'chapter',prompt:storyContext(s,n)+`\n\nCHƯƠNG ${n}: Viết chương tiếp theo theo kế hoạch. Độ dài mục tiêu ${s.chapterLength||1500} từ. Chỉ trả nội dung chương.`})}
function storyOverlay(html){let d=$('#storyWorkbenchDialog');if(!d){d=document.createElement('dialog');d.id='storyWorkbenchDialog';d.className='story-dialog';document.body.append(d)}d.innerHTML=`<div class="dialog-head"><h2>Xưởng truyện dài</h2><button type="button" data-story-close>×</button></div>${html}`;d.showModal()}
function storyWorkbench(s){const sd=storyData(s),chs=storyChapters(s),alerts=storyThreadAlerts(s,Math.max(1,...chs.map(c=>Number(c.chapterNumber)||0))+1);storyOverlay(`<div class="story-tabs"><button data-story-tab="plan">Dàn ý</button><button data-story-tab="memory">Trí nhớ & nút thắt</button><button data-story-tab="translate">Dịch thuật</button><button data-story-tab="import">Nhập dữ liệu local</button></div><div class="notice"><div><strong>${esc(s.title)}</strong><p>Tập → Tuyến truyện → Kế hoạch chương → Cảnh. AI tạo bản nháp; người dùng duyệt trước khi xuất bản.</p></div></div><section class="panel"><div class="panel-head"><h2>Trạng thái</h2><span>${chs.length} chương · ${sd.plans.length} mục dàn ý · ${sd.memories.length} ghi nhớ</span></div>${alerts.length?`<p class="error-text">${alerts.length} nút thắt đã đến/quá mốc cần xem xét.</p>`:'<p class="help-text">Không có nút thắt quá mốc.</p>'}<div class="actions"><button class="primary" data-story-next="${s.id}">Viết chương tiếp theo</button><button data-story-tab="plan">Quản lý dàn ý</button><button data-story-tab="translate">Dịch chương</button></div></section><div id="storyTabBody"></div>`);storyTab(s,'plan')}
function storyTab(s,tab){const box=$('#storyTabBody');if(!box)return;const sd=storyData(s);if(tab==='plan')box.innerHTML=`<section class="panel mt"><div class="panel-head"><h2>Dàn ý phân cấp</h2><button data-story-addplan="${s.id}">+ Thêm</button></div>${sd.plans.map(p=>`<div class="row"><div><strong>${esc(storyPlanPath(s,p))}</strong><small>${esc(storyKinds[p.kind]||'Ghi chú')} ${p.startChapter?'· chương '+p.startChapter+(p.endChapter!==p.startChapter?'–'+p.endChapter:''):''}</small></div><button data-story-delplan="${p.id}" data-series="${s.id}">Xóa</button></div>`).join('')||'<p class="help-text">Chưa có dàn ý. Có thể nhập từ bản local hoặc thêm mới.</p>'}</section>`;
if(tab==='memory')box.innerHTML=`<section class="panel mt"><div class="panel-head"><h2>Trí nhớ & nút thắt</h2><button data-story-addmemory="${s.id}">+ Thêm</button></div>${sd.memories.map(m=>`<div class="row"><div><strong>${esc(m.title)}</strong><small>${esc(m.type)} · chương ${Number(m.chapter)||1} · ${m.confirmed?'Đã xác nhận':'Chưa xác nhận'}${m.type==='Nút thắt'?' · '+esc(storyThreadStates[m.threadStatus||'open']):''}</small></div><button data-story-delmemory="${m.id}" data-series="${s.id}">Xóa</button></div>`).join('')||'<p class="help-text">Chưa có trí nhớ.</p>'}</section>`;
if(tab==='translate'){const chs=storyChapters(s);box.innerHTML=`<section class="panel mt"><h2>Dịch thuật Anh – Trung giản thể – Việt</h2><p class="help-text">Tách theo đoạn có mã, dịch theo nhóm, rà soát độc lập rồi mới duyệt/xuất. Bản dịch được lưu riêng theo chương, không ghi đè bản gốc.</p><label>Chương<select id="storyTranslateChapter">${chs.map(c=>`<option value="${c.id}">Chương ${esc(c.chapterNumber||'')} — ${esc(c.title)}</option>`).join('')}</select></label><label>Ngôn ngữ đích<select id="storyTargetLang"><option value="en">English</option><option value="zh">中文（简体）</option><option value="vi">Tiếng Việt</option></select></label><div class="actions"><button class="primary" data-story-translate="${s.id}">Tạo bản nháp dịch trong Xưởng</button></div></section>`}
if(tab==='import')box.innerHTML=`<section class="panel mt"><h2>Nhập dữ liệu XUONG_TRUYEN local</h2><p class="help-text">Không xóa dữ liệu local. Xưởng tạo bản sao lưu trước khi nhập, đối chiếu ID và dấu vân tay nội dung để chống trùng.</p><textarea id="storyImportJson" rows="10" placeholder='Dán JSON {"version":1,"books":[...]}'></textarea><div class="actions"><button data-story-preview-import="${s.id}">Kiểm tra dữ liệu</button><button class="primary" data-story-import="${s.id}">Sao lưu & nhập</button></div><pre id="storyImportReport" class="history-body"></pre></section>`}
function storyFingerprint(v){let h=2166136261,s=JSON.stringify(v);for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
function storyMapLocalBook(target,b){const sd=storyData(target);for(const p of b.plans||[])if(!sd.plans.some(x=>x.id===p.id))sd.plans.push(structuredClone(p));for(const m of b.memories||[])if(!sd.memories.some(x=>x.id===m.id))sd.memories.push(structuredClone(m));for(const c of b.characters||[])if(!sd.characters.some(x=>x.id===c.id))sd.characters.push(structuredClone(c));target.synopsis=target.synopsis||b.premise||'';target.world=target.world||b.world||'';target.genre=target.genre||b.genre||'';target.chapterLength=target.chapterLength||b.length||1500;for(const c of b.chapters||[]){const key='xt:'+b.id+':chapter:'+c.id,fp=storyFingerprint([c.number,c.title,c.body]);if(sd.importKeys.includes(key)||db.content.some(x=>x.seriesId===target.id&&x.importFingerprint===fp))continue;db.content.push({id:uid(),title:c.title||('Chương '+c.number),channelId:target.channelId,seriesId:target.id,status:statuses[c.status]?c.status:'draft',kind:'Chương truyện',chapterNumber:Number(c.number)||1,productionTask:'chapter',body:c.body||'',summary:c.summary||'',prompt:'',history:Array.isArray(c.history)?c.history:[],translations:c.translations||{},importFingerprint:fp,importSource:key,updatedAt:new Date().toISOString()});sd.importKeys.push(key)}}
function storyImportPreview(raw){const data=JSON.parse(raw);if(data?.version!==1||!Array.isArray(data.books))throw Error('Sai định dạng XUONG_TRUYEN.');return `${data.books.length} bộ truyện · ${data.books.reduce((n,b)=>n+(b.chapters?.length||0),0)} chương · ${data.books.reduce((n,b)=>n+(b.plans?.length||0),0)} mục dàn ý · ${data.books.reduce((n,b)=>n+(b.memories?.length||0),0)} ghi nhớ.`}
const storyWebnovelPage=webnovelPage;webnovelPage=function(){let html=storyWebnovelPage();for(const s of db.series.filter(s=>s.channelId===findWebnovelChannel()?.id))html=html.replace(`<button data-edit="series" data-id="${s.id}">Hồ sơ truyện</button>`,`<button data-edit="series" data-id="${s.id}">Hồ sơ truyện</button><button data-story-open="${s.id}">Bộ truyện / Webnovel</button>`);return html};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const sid=b.dataset.series||b.dataset.storyOpen||b.dataset.storyNext||b.dataset.storyAddplan||b.dataset.storyAddmemory||b.dataset.storyTranslate||b.dataset.storyPreviewImport||b.dataset.storyImport,s=db.series.find(x=>x.id===sid);if(b.dataset.storyOpen&&s)return storyWorkbench(s);if(b.dataset.storyClose)return $('#storyWorkbenchDialog')?.close();if(b.dataset.storyTab&&$('#storyWorkbenchDialog')?.open){const active=db.series.find(x=>x.id===($('#storyWorkbenchDialog').dataset.series||''))||s||db.series.find(x=>$('#storyWorkbenchDialog').textContent.includes(x.title));if(active)storyTab(active,b.dataset.storyTab);return}if(b.dataset.storyNext&&s){$('#storyWorkbenchDialog')?.close();return storyCreateDraft(s)}if(b.dataset.storyAddplan&&s){const title=prompt('Tên mục dàn ý');if(!title)return;const kind=prompt('Loại: volume / arc / chapter / scene / note','arc')||'arc';if(!storyKinds[kind])return toast('Loại dàn ý không hợp lệ.');const start=kind==='note'?0:Number(prompt('Chương bắt đầu','1')||1),end=['chapter','scene'].includes(kind)?start:Number(prompt('Chương kết thúc',String(start||1))||start);storyData(s).plans.push({id:uid(),title,body:prompt('Nội dung / mục tiêu','')||'',kind,parentId:'',startChapter:start,endChapter:end,order:storyData(s).plans.length});if(save())storyWorkbench(s)}if(b.dataset.storyAddmemory&&s){const title=prompt('Tên ghi nhớ / nút thắt');if(!title)return;const type=prompt('Loại: Sự kiện / Nút thắt / Dòng thời gian / Quy tắc','Sự kiện')||'Sự kiện';storyData(s).memories.push({id:uid(),title,body:prompt('Nội dung','')||'',type,chapter:Number(prompt('Chương ghi nhận','1')||1),confirmed:false,threadStatus:'open',dueChapter:0,resolvedChapter:0,resolution:''});if(save())storyWorkbench(s)}if(b.dataset.storyDelplan&&s){storyData(s).plans=storyData(s).plans.filter(x=>x.id!==b.dataset.storyDelplan);if(save())storyWorkbench(s)}if(b.dataset.storyDelmemory&&s){storyData(s).memories=storyData(s).memories.filter(x=>x.id!==b.dataset.storyDelmemory);if(save())storyWorkbench(s)}if(b.dataset.storyTranslate&&s){const c=db.content.find(x=>x.id===$('#storyTranslateChapter')?.value),target=$('#storyTargetLang')?.value;if(!c)return toast('Chưa có chương để dịch.');c.translations??={};if(c.translations[target]&&!await uiConfirm('Đã có bản dịch ngôn ngữ này. Tạo lại bản nháp mới?'))return;const lang={en:'English',zh:'中文（简体）',vi:'Tiếng Việt'}[target];const segments=(c.body||'').replace(/\r\n?/g,'\n').split(/\n[\t ]*\n+/).filter(x=>x.trim()).map((source,i)=>({id:'p'+String(i+1).padStart(4,'0'),source,target:'',notes:''}));c.translations[target]={sourceBody:c.body,sourceTitle:c.title,targetLang:target,status:'draft',segments,checks:{},reviews:[],history:[]};const payload=segments.map(x=>({id:x.id,source:x.source}));openEditor('content',c.id);const ta=$('#fields textarea[name="prompt"]');if(ta)ta.value=`Translate every supplied paragraph faithfully into natural ${lang}. Do not summarize, omit, merge or invent paragraphs. Preserve IDs exactly. SERIES: ${s.title}. GLOSSARY: ${JSON.stringify(storyData(s).translationConfig.terms||[])}. TASK: ${JSON.stringify(payload)}. Return one JSON object, no markdown: {"title":"translated chapter title","segments":[{"id":"p0001","target":"complete translation","notes":"ambiguities in Vietnamese, or empty string"}]}.`;$('#storyWorkbenchDialog')?.close();toast('Đã tạo bản nháp dịch. Lưu chương rồi dùng ChatGPT Bridge chung.')}if(b.dataset.storyPreviewImport&&s){try{$('#storyImportReport').textContent=storyImportPreview($('#storyImportJson').value)}catch(err){$('#storyImportReport').textContent='Lỗi: '+err.message}}if(b.dataset.storyImport&&s){try{const raw=$('#storyImportJson').value,data=JSON.parse(raw);storyImportPreview(raw);const before=JSON.stringify(db),stamp=new Date().toISOString().replace(/[:.]/g,'-');localStorage.setItem('xuong-noi-dung-pre-import-'+stamp,before);const match=data.books.find(x=>x.id===s.importSourceId)||data.books.find(x=>x.title.trim().toLowerCase()===s.title.trim().toLowerCase())||(data.books.length===1?data.books[0]:null);if(!match)throw Error('Không xác định được bộ truyện tương ứng. Hãy nhập từng bộ hoặc đặt tên trùng.');storyMapLocalBook(s,match);s.importSourceId=match.id;if(!save()){db=JSON.parse(before);return}storyWorkbench(s);toast('Đã nhập an toàn. Dữ liệu local không bị xóa.')}catch(err){toast('Không nhập: '+err.message)}}});
const storyOriginalWorkbench=storyWorkbench;storyWorkbench=function(s){storyOriginalWorkbench(s);$('#storyWorkbenchDialog').dataset.series=s.id};
